function openEmpty() {
    var ga = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
    //MSSCUSTODY-4593
    ga.addParam('sysparm_name', 'getDefaultOwningBusiness');
    ga.getXMLAnswer(handleResponse);

    function handleResponse(response) {
        var url = "/x_hsb11_mss_c_proc_mss_custody_task_list.do?sysparm_view=bulk_automated_tasks&sysparm_userpref_module=a46412e01b4f6910ff37eb14b24bcb65&sysparm_fixed_query=active=true^bulk_idISEMPTY^trade_task_type=Maker^trade_id.source_system=GHSS^trade_id.trade_lifecycle_status!=TradOnHldDueToSnctns^trade_case_id.triggered_by.status!=Trade On-Hold due to Sanctions&sysparm_query=trade_id.settlement_dateONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()^trade_id.owning_businessIN"+ response;
        g_navigation.open(url);
    }
}
